        account = self.get_account()
        current_equity = float(account.get("equity", 0.0))
        last_equity = float(account.get("last_equity", current_equity))

        if last_equity <= 0:
            logger.error("Invalid last_equity (<= 0). Bypassing drawdown check.")
            return False

        daily_drawdown = (last_equity - current_equity) / last_equity

        if daily_drawdown >= settings.MAX_DAILY_DRAWDOWN_PCT:
            logger.critical(
                "Circuit Breaker Triggered: Daily drawdown %.2f%% exceeds max allowed %.2f%%. Halting purchases.",
                daily_drawdown * 100,
                settings.MAX_DAILY_DRAWDOWN_PCT * 100,
            )
            return True

